refentry.refsect1:
&reftitle.description;
booldbase_replace_record resourcedatabase arraydata intnumber
Sostituisce il record indicato nel database con i dati indicati.

&reftitle.changelog;





    &Version;
    &Description;





    PECL dbase 7.0.0

     database ora è una resource
     invece di un int.

  &reftitle.examples;



    Aggiornamento di un record nel database


<?php

// apre in modalità lettura-scrittura
$db = dbase_open('/tmp/test.dbf', 2);

if ($db) {
  // ottiene la riga precedente
  $row = dbase_get_record_with_names($db, 1);

  // rimuove l'elemento 'deleted'
  unset($row['deleted']);

  // Aggiorna il campo della data con il timestamp corrente
  $row['date'] = date('Ymd');

  // converte la riga in un array indicizzato
  $row = array_values($row);

  // Sostituisce il record
  dbase_replace_record($db, $row, 1);
  dbase_close($db);
}

?>
